"""Controlled adaptive target-profile experiment generated by AI Lab."""

from __future__ import annotations

from typing import Any


def run(
    cache,
    signal_name: str,
    direction: str,
    fraction: float,
    targets: list[str],
) -> dict[str, Any]:
    """Report target event rates for one fixed regime.

    No target is selected by this experiment. Every supplied target
    is reported in the same deterministic order.
    """
    mask = cache.tail_masks[
        f"{signal_name}|{direction}|{fraction}"
    ]

    window = cache.window_masks[
        "window_2"
    ][
        "validation"
    ]

    rows = []

    for target_name in targets:
        target = cache.targets[
            target_name
        ]

        selected = (
            window
            & mask
        )

        valid = selected

        n = int(
            valid.sum()
        )

        events = int(
            (
                target[valid] > 0
            ).sum()
        ) if n else 0

        rows.append(
            {
                "target": target_name,
                "n": n,
                "events": events,
                "event_rate": (
                    events / n
                    if n
                    else None
                ),
            }
        )

    return {
        "experiment_family": "adaptive_target_profile_experiment",
        "rows": rows,
    }
